actions.script:
if (ec.user.userId && !ec.user.isInGroup('ADMIN')) throw new Error('Demo loading requires system administration')
const nowMillis = ec.user.timestampMillis(ec.user.nowTimestamp)
// the server's local day, as the demo data's fixed dates are read
const now = new Date(nowMillis)
const after = (days, hour = 0) => String(new Date(now.getFullYear(), now.getMonth(), now.getDate() + days, hour).getTime())
// a wall-clock time in a zone: the load day there, a calendar day counted in UTC (no DST in the count), the hour read back in
// the zone (DST kept), as load#EventDatesDemo
const pad = (n) => String(n).padStart(2, '0')
const afterIn = (zone, days, hour) => {
    const [year, month, date] = String(ec.l10n.format(String(nowMillis), 'yyyy-MM-dd', null, zone)).split('-').map(Number)
    const d = new Date(Date.UTC(year, month - 1, date + days))
    const text = d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' + pad(hour) + ':00:00'
    return String(ec.user.timestampMillis(ec.l10n.parseTimestamp(text, 'yyyy-MM-dd HH:mm:ss', null, zone)))
}
const move = (entityName, keys, fields) => {
    if (ec.entity.find(entityName).condition(keys).disableAuthz().one() == null) {
        ec.logger.warn('The campaign dates demo found no ' + entityName + ' ' + JSON.stringify(keys) + '; not moved')
        return
    }
    ec.service.sync().name('update#' + entityName).parameters(Object.assign({}, keys, fields)).disableAuthz().call()
}
const CAMPAIGN = 'mantle.marketing.campaign.MarketingCampaign'
move(CAMPAIGN, {marketingCampaignId: 'BOSS_MKT_CMP_SPRING'}, {fromDate: after(-14), thruDate: after(77), startDate: after(-13, 9)})
move(CAMPAIGN, {marketingCampaignId: 'BOSS_MKT_CMP_SPRING_EVENT'}, {fromDate: after(56), thruDate: after(58)})
move(CAMPAIGN, {marketingCampaignId: 'BOSS_MKT_CMP_HOLIDAY'}, {fromDate: after(16), thruDate: after(46)})
move(CAMPAIGN, {marketingCampaignId: 'BOSS_MKT_CMP_SERVICES'}, {fromDate: after(16), thruDate: after(105)})
const SEND = 'mantle.marketing.campaign.CampaignSend'
const send = ec.entity.find(SEND).condition({campaignSendId: 'BOSS_MKT_SEND_DEC'}).disableAuthz().one()
if (send == null) {
    ec.logger.warn('The campaign dates demo found no send BOSS_MKT_SEND_DEC; not moved')
} else {
    scheduledDate = afterIn(send.scheduleTimeZone || 'America/Chicago', 16, 8)
    move(SEND, {campaignSendId: 'BOSS_MKT_SEND_DEC'}, {scheduledDate})
}

if (ec.user.userId && !ec.user.isInGroup('ADMIN')) throw new Error('Demo loading requires system administration')
// wall-clock times in each offer's time zone (America/Denver, as PASS shows them), whatever the server's zone: the load day
// there, a calendar day counted in UTC (no DST in the count), the hour read back in the zone (DST kept)
const nowText = String(ec.user.timestampMillis(ec.user.nowTimestamp))
const zoneOf = (registrationPolicyId) => {
    const offer = ec.entity.find('mantle.work.registration.EventRegistrationPolicy').condition({registrationPolicyId}).disableAuthz().one()
    return (offer && offer.timeZone) || 'America/Denver'
}
const dayOn = (zone, afterDays, weekDay) => {
    const [year, month, date] = String(ec.l10n.format(nowText, 'yyyy-MM-dd', null, zone)).split('-').map(Number)
    const day = new Date(Date.UTC(year, month - 1, date + afterDays))
    return new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate() + ((weekDay - day.getUTCDay() + 7) % 7)))
}
const pad = (n) => String(n).padStart(2, '0')
const at = (zone, day, hour, plusDays = 0) => {
    const d = new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate() + plusDays))
    const text = d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' + pad(hour) + ':00:00'
    return String(ec.user.timestampMillis(ec.l10n.parseTimestamp(text, 'yyyy-MM-dd HH:mm:ss', null, zone)))
}
const move = (entityName, keys, fields) => {
    const found = ec.entity.find(entityName).condition(keys).disableAuthz().one()
    if (found == null) {
        ec.logger.warn('The event dates demo found no ' + entityName + ' ' + JSON.stringify(keys) + '; not moved')
        return
    }
    ec.service.sync().name('update#' + entityName).parameters(Object.assign({}, keys, fields)).disableAuthz().call()
}
const webinarZone = zoneOf('BOSS_MKT_OFFER_WEBINAR')
const workshopZone = zoneOf('BOSS_MKT_OFFER_WORKSHOP')
const webinar = dayOn(webinarZone, 70, 4)
const workshop = dayOn(workshopZone, 118, 6)
webinarStart = at(webinarZone, webinar, 18)
workshopStart = at(workshopZone, workshop, 9)
move('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_MKT_EV_WEBINAR'},
    {estimatedStartDate: webinarStart, estimatedCompletionDate: at(webinarZone, webinar, 19)})
move('mantle.work.registration.EventRegistrationPolicy', {registrationPolicyId: 'BOSS_MKT_OFFER_WEBINAR'},
    {occurrenceStart: webinarStart, occurrenceEnd: at(webinarZone, webinar, 19)})
move('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_MKT_EV_WORKSHOP'},
    {estimatedStartDate: workshopStart, estimatedCompletionDate: at(workshopZone, workshop, 12)})
move('mantle.work.registration.EventRegistrationPolicy', {registrationPolicyId: 'BOSS_MKT_OFFER_WORKSHOP'},
    {occurrenceStart: workshopStart, occurrenceEnd: at(workshopZone, workshop, 12), closesDate: at(workshopZone, workshop, 17, -1)})
